/**
 * Books one place for the viewer in a class of the gym of their own active membership, while the class is
 * scheduled and has not started and a place is left. The same `client_request_id` again returns that booking
 * (`200`), even after it was cancelled, and takes no place. No waitlist exists: a full class is a `409`.
 * Creates no training session, relationship, payment or entitlement.
 *
 * * `not_found` - not one of the viewer's own memberships (or bookings), or an unknown or another gym's class.
 * * `conflict` - `details.gym_member` is the membership's status when it is not `active` (a request, an ended,
 *   rejected or cancelled membership books nothing).
 *
 * * `conflict` - `details.class_occurrence: "full"` (no place left; `details.capacity`), `"cancelled"` or
 *   `"started"`; `details.class_booking: "already_booked"` (a confirmed booking of this class exists for the
 *   member); `details.client_request_id: "reused"` (the key named another booking); a draft gym
 *   (`details.setup_status`).
 *
 * * `validation_error` - a missing, invalid or unknown field.
 * * `rate_limited` - 60 bookings and cancellations per 10 minutes per user.
 * @summary Book a place in a class
 */
export const bookMyGymClass = async (gymMemberId: string,
    gymClassBookingRequest: GymClassBookingRequest, options?: Parameters<typeof apiFetch>[1]): Promise<MyGymClassBookingResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<MyGymClassBookingResponse>(getBookMyGymClassUrl(gymMemberId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(gymClassBookingRequest)
  }
);}





